-- Java <-> Web bridge migration -- Apply on the same MySQL schema used by both apps (ex: greenledger).
-- 1) ML predictions CREATE TABLE IF NOT EXISTS ml_predictions ( id BIGINT AUTO_INCREMENT PRIMARY KEY, evaluation_id INT NULL, project_id INT NULL, predicted_esg_score INT NULL, credibility_score INT NULL, carbon_risk VARCHAR(50) NULL, decision VARCHAR(50) NULL, recommendations TEXT NULL, model_version VARCHAR(120) NULL, created_by_user_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ml_predictions_project_created (project_id, created_at), INDEX idx_ml_predictions_eval_created (evaluation_id, created_at) );
-- 2) ML decision snapshots CREATE TABLE IF NOT EXISTS ml_decision_snapshots ( id BIGINT AUTO_INCREMENT PRIMARY KEY, project_id INT NULL, evaluation_id INT NULL, project_name VARCHAR(255) NULL, decision VARCHAR(50) NULL, confidence DECIMAL(10,6) NULL, score DECIMAL(10,6) NULL, compliance DECIMAL(10,6) NULL, min_note INT NULL, esg_score INT NULL, factors LONGTEXT NULL, explanation LONGTEXT NULL, recommendations LONGTEXT NULL, created_by_user_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_ml_snapshots_project_created (project_id, created_at), INDEX idx_ml_snapshots_eval_created (evaluation_id, created_at) );
ALTER TABLE ml_decision_snapshots ADD COLUMN IF NOT EXISTS project_id INT NULL, ADD COLUMN IF NOT EXISTS evaluation_id INT NULL, ADD COLUMN IF NOT EXISTS project_name VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS decision VARCHAR(50) NULL, ADD COLUMN IF NOT EXISTS confidence DECIMAL(10,6) NULL, ADD COLUMN IF NOT EXISTS score DECIMAL(10,6) NULL, ADD COLUMN IF NOT EXISTS compliance DECIMAL(10,6) NULL, ADD COLUMN IF NOT EXISTS min_note INT NULL, ADD COLUMN IF NOT EXISTS esg_score INT NULL, ADD COLUMN IF NOT EXISTS factors LONGTEXT NULL, ADD COLUMN IF NOT EXISTS explanation LONGTEXT NULL, ADD COLUMN IF NOT EXISTS recommendations LONGTEXT NULL, ADD COLUMN IF NOT EXISTS created_by_user_id BIGINT NULL, ADD COLUMN IF NOT EXISTS created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
-- 3) PDF export logs CREATE TABLE IF NOT EXISTS pdf_exports ( id BIGINT AUTO_INCREMENT PRIMARY KEY, evaluation_id INT NULL, project_id INT NULL, provider VARCHAR(80) NULL, output_path VARCHAR(1024) NULL, status VARCHAR(60) NULL, error_message TEXT NULL, created_by_user_id BIGINT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_pdf_exports_project_created (project_id, created_at), INDEX idx_pdf_exports_eval_created (evaluation_id, created_at) );
-- 4) Carbon metric table used by Java service CREATE TABLE IF NOT EXISTS carbon_metric ( id BIGINT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, evaluation_id INT NULL, metric_date DATE NULL, scope1_tco2 DECIMAL(14,6) NULL, scope2_tco2 DECIMAL(14,6) NULL, scope3_tco2 DECIMAL(14,6) NULL, total_tco2 DECIMAL(14,6) NULL, method VARCHAR(120) NULL, data_quality_score DECIMAL(10,4) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_carbon_metric_project_date (project_id, metric_date), INDEX idx_carbon_metric_eval_date (evaluation_id, metric_date) );
ALTER TABLE carbon_metric ADD COLUMN IF NOT EXISTS evaluation_id INT NULL, ADD COLUMN IF NOT EXISTS metric_date DATE NULL, ADD COLUMN IF NOT EXISTS scope1_tco2 DECIMAL(14,6) NULL, ADD COLUMN IF NOT EXISTS scope2_tco2 DECIMAL(14,6) NULL, ADD COLUMN IF NOT EXISTS scope3_tco2 DECIMAL(14,6) NULL, ADD COLUMN IF NOT EXISTS total_tco2 DECIMAL(14,6) NULL, ADD COLUMN IF NOT EXISTS method VARCHAR(120) NULL, ADD COLUMN IF NOT EXISTS data_quality_score DECIMAL(10,4) NULL, ADD COLUMN IF NOT EXISTS created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;

package Services;

import Models.dto.ProjectData;

/**
 * Baseline Emission Service — pure math, no API.
 *
 * Calculates what emissions WOULD have been without the project
 * (used to compute avoided_tco2 = baseline - actual).
 *
 * Baseline factors are slightly higher than actual factors
 * to represent the counterfactual scenario.
 */
public class BaselineEmissionService {

    // Baseline factors (tCO2e per unit) — higher than actual
    private static final double BASELINE_ENERGY    = 0.0006;   // tCO2e/kWh
    private static final double BASELINE_TRANSPORT = 0.00012;  // tCO2e/km
    private static final double BASELINE_MATERIAL  = 0.0015;   // tCO2e/tonne (embedded)
    private static final double BASELINE_WASTE     = 0.0009;   // tCO2e/tonne

    /**
     * Calculate baseline tCO2e for a project.
     */
    public double calculateBaseline(ProjectData project) {
        double energy    = pos(project.getConsommationEnergie());
        double transport = pos(project.getDistanceTransport());
        double material  = pos(project.getQuantiteMateriau());
        double waste     = pos(project.getDechetsGeneres());

        // Auto-scale energy
        String unit = project.getUniteEnergie() != null ? project.getUniteEnergie() : "kWh";
        if (energy > 0 && energy < 10_000 && "kwh".equalsIgnoreCase(unit)) {
            energy = energy * 1000;
        }

        return r3((energy    * BASELINE_ENERGY)
                + (transport * BASELINE_TRANSPORT)
                + (material  * BASELINE_MATERIAL)
                + (waste     * BASELINE_WASTE));
    }

    /**
     * Calculate avoided tCO2e = max(0, baseline - actual).
     */
    public double calculateAvoided(ProjectData project, double actualTco2) {
        double baseline = calculateBaseline(project);
        return Math.max(0.0, r3(baseline - actualTco2));
    }

    private double pos(Double v) { return (v != null && v > 0) ? v : 0.0; }
    private double r3(double v)  { return Math.round(v * 1000.0) / 1000.0; }
}

package Services;

import Models.dto.ProjectData;

/**
 * Baseline Emission Service — pure math, no API.
 *
 * Calculates what emissions WOULD have been without the project
 * (used to compute avoided_tco2 = baseline - actual).
 *
 * Baseline factors are slightly higher than actual factors
 * to represent the counterfactual scenario.
 */
public class BaselineEmissionService {

    // Baseline factors (tCO2e per unit) — higher than actual
    private static final double BASELINE_ENERGY    = 0.0006;   // tCO2e/kWh
    private static final double BASELINE_TRANSPORT = 0.00012;  // tCO2e/km
    private static final double BASELINE_MATERIAL  = 0.0015;   // tCO2e/tonne (embedded)
    private static final double BASELINE_WASTE     = 0.0009;   // tCO2e/tonne

    /**
     * Calculate baseline tCO2e for a project.
     */
    public double calculateBaseline(ProjectData project) {
        double energy    = pos(project.getConsommationEnergie());
        double transport = pos(project.getDistanceTransport());
        double material  = pos(project.getQuantiteMateriau());
        double waste     = pos(project.getDechetsGeneres());

        energy = toEnergyKwh(energy, project.getUniteEnergie());

        return r3((energy    * BASELINE_ENERGY)
                + (transport * BASELINE_TRANSPORT)
                + (material  * BASELINE_MATERIAL)
                + (waste     * BASELINE_WASTE));
    }

    /**
     * Calculate avoided tCO2e = max(0, baseline - actual).
     */
    public double calculateAvoided(ProjectData project, double actualTco2) {
        double baseline = calculateBaseline(project);
        return Math.max(0.0, r3(baseline - actualTco2));
    }

    private double toEnergyKwh(double value, String unit) {
        if (value <= 0) return 0.0;
        String normalized = unit != null ? unit.toLowerCase().trim() : "kwh";
        return switch (normalized) {
            case "mwh" -> value * 1_000.0;
            case "gwh" -> value * 1_000_000.0;
            case "wh"  -> value / 1_000.0;
            default     -> value;
        };
    }

    private double pos(Double v) { return (v != null && v > 0) ? v : 0.0; }
    private double r3(double v)  { return Math.round(v * 1000.0) / 1000.0; }
}

package Services;

import DataBase.MyConnection;
import Models.dto.CarbonMetricResult;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

/**
 * Read service for persisted carbon metrics used by both web and Java flows.
 */
public class CarbonMetricService {

    private static final String SELECT_BASE =
            "SELECT id, project_id, evaluation_id, metric_date, scope1_tco2, scope2_tco2, scope3_tco2, total_tco2, method, data_quality_score, created_at " +
            "FROM carbon_metric ";

    public CarbonMetricResult findLatestByProject(int projectId) {
        String sql = SELECT_BASE + "WHERE project_id=? ORDER BY metric_date DESC, id DESC LIMIT 1";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return mapRow(rs);
                }
            }
        } catch (SQLException ex) {
            System.err.println("[CARBON] findLatestByProject failed: " + ex.getMessage());
        }
        return null;
    }

    public CarbonMetricResult findLatestByEvaluation(int evaluationId) {
        String sql = SELECT_BASE + "WHERE evaluation_id=? ORDER BY metric_date DESC, id DESC LIMIT 1";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, evaluationId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return mapRow(rs);
                }
            }
        } catch (SQLException ex) {
            System.err.println("[CARBON] findLatestByEvaluation failed: " + ex.getMessage());
        }
        return null;
    }

    private CarbonMetricResult mapRow(ResultSet rs) throws SQLException {
        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(nullableDouble(rs, "scope1_tco2"));
        result.setScope2Tco2(nullableDouble(rs, "scope2_tco2"));
        result.setScope3Tco2(nullableDouble(rs, "scope3_tco2"));
        result.setTotalTco2(nullableDouble(rs, "total_tco2"));
        result.setMethod(rs.getString("method"));
        result.setDataQualityScore(nullableDouble(rs, "data_quality_score"));
        return result;
    }

    private Double nullableDouble(ResultSet rs, String columnName) throws SQLException {
        double value = rs.getDouble(columnName);
        return rs.wasNull() ? null : value;
    }
}

package Services;

import Models.dto.CarbonMetricResult;
import Models.dto.ProjectData;
import Utils.EnvLoader;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.apache.hc.client5.http.classic.methods.HttpPost;
import org.apache.hc.client5.http.config.RequestConfig;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.core5.http.io.entity.EntityUtils;
import org.apache.hc.core5.http.io.entity.StringEntity;
import org.apache.hc.core5.util.Timeout;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Climatiq API Client
 *
 * POST https://api.climatiq.io/data/v1/estimate
 * Returns scope1, scope2, scope3 in kgCO2e → converted to tCO2e
 *
 * Fallback emission factors (when API unavailable):
 *   Transport: 0.0001 tCO2e/km
 *   Waste:     0.5    tCO2e/tonne
 *   Energy:    0.0005 tCO2e/kWh
 *   Material:  2.0    tCO2e/tonne
 */
public class ClimatiqApiClient {

    private static final String BASE_URL     = "https://api.climatiq.io";
    private static final String DATA_VERSION = "^32";  // wildcard — matches latest 32.x
    private static final int    TIMEOUT_SEC  = 15;

    // Fallback factors
    private static final double FACTOR_TRANSPORT = 0.0001;
    private static final double FACTOR_WASTE     = 0.5;
    private static final double FACTOR_ENERGY    = 0.0005;
    private static final double FACTOR_MATERIAL  = 2.0;

    private final String apiKey;
    private final Gson   gson = new Gson();

    public ClimatiqApiClient() {
        this.apiKey = EnvLoader.get("CLIMATIQ_API_KEY", "");
        if (apiKey.isBlank()) {
            System.err.println("[Climatiq] CLIMATIQ_API_KEY not set — will use fallback heuristics");
        } else {
            System.out.println("[Climatiq] API client initialized");
        }
    }

    // ── Main entry point ──────────────────────────────────────────────────

    public CarbonMetricResult estimateProjectEmissions(ProjectData project) {
        List<String> errors = new ArrayList<>();

        if (apiKey.isBlank()) {
            return fallback(project, errors);
        }

        // Smart unit scaling — mirror Python _autoscale_energy logic:
        // if energy < 10 000 and unit is kWh, treat value as MWh → convert to kWh
        double energyValue = pos(project.getConsommationEnergie());
        String energyUnit  = project.getUniteEnergie() != null ? project.getUniteEnergie() : "kWh";
        double energyKwh;
        if (energyValue > 0 && energyValue < 10_000 && "kwh".equalsIgnoreCase(energyUnit)) {
            // Value is actually MWh — convert to kWh once
            energyKwh = energyValue * 1_000.0;
        } else {
            energyKwh = toEnergyKwh(energyValue, energyUnit);
        }
        double distanceKm  = pos(project.getDistanceTransport());
        double materialTon = pos(project.getQuantiteMateriau());

        Double scope1 = null, scope2 = null, scope3 = null;

        // Scope 1: Transport
        if (distanceKm > 0 && materialTon > 0) {
            scope1 = estimateWithCandidates(
                resolveTransportIds(project.getTypeTransport()),
                Map.of("weight", Math.max(0.1, materialTon), "weight_unit", "t",
                       "distance", distanceKm, "distance_unit", "km"),
                errors);
        }

        // Scope 2: Energy
        if (energyKwh > 0) {
            scope2 = estimateWithCandidates(
                List.of(
                    "electricity-supply_grid-source_residual_mix",
                    "electricity-supply_grid-source_supplier_mix",
                    "electricity-supply_grid-source_geothermal_energy"
                ),
                Map.of("energy", energyKwh, "energy_unit", "kWh"),
                errors);
        }

        // Scope 3: Materials
        if (materialTon > 0) {
            scope3 = estimateWithCandidates(
                resolveMaterialIds(project.getTypeMateriau()),
                Map.of("weight", Math.max(0.1, materialTon), "weight_unit", "t"),
                errors);
        }

        // If all scopes failed, use fallback
        if (scope1 == null && scope2 == null && scope3 == null) {
            System.err.println("[Climatiq] All API calls failed — using fallback");
            return fallback(project, errors);
        }

        double s1 = scope1 != null ? scope1 : fallbackScope1(project);
        double s2 = scope2 != null ? scope2 : fallbackScope2(project);
        double s3 = scope3 != null ? scope3 : fallbackScope3(project);
        double total = r3(s1 + s2 + s3);

        // Guardrail: only revert to fallback if Climatiq result is > 10× fallback
        // (catches clearly wrong API responses, not just higher-precision results)
        double fb = r3(fallbackScope1(project) + fallbackScope2(project) + fallbackScope3(project));
        if (fb > 0.1 && total > fb * 10.0) {
            System.err.printf("[Climatiq] Guardrail: API=%.3f > 10× fallback=%.3f — reverting%n", total, fb);
            return fallback(project, errors);
        }

        System.out.printf("[Climatiq] ✓ API result: scope1=%.3f scope2=%.3f scope3=%.3f total=%.3f tCO2e%n",
            s1, s2, s3, total);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(r3(s1));
        result.setScope2Tco2(r3(s2));
        result.setScope3Tco2(r3(s3));
        result.setTotalTco2(total);
        result.setMethod("CLIMATIQ_API_V1_ESTIMATE");
        result.setProviderErrors(errors);
        return result;
    }

    // ── Single API call ───────────────────────────────────────────────────

    private Double estimateSingle(String activityId, Map<String, Object> params, List<String> errors) {
        String url = BASE_URL + "/data/v1/estimate";

        JsonObject emissionFactor = new JsonObject();
        emissionFactor.addProperty("activity_id", activityId);
        emissionFactor.addProperty("data_version", DATA_VERSION);

        JsonObject body = new JsonObject();
        body.add("emission_factor", emissionFactor);
        body.add("parameters", gson.toJsonTree(params));

        RequestConfig config = RequestConfig.custom()
            .setConnectionRequestTimeout(Timeout.of(TIMEOUT_SEC, TimeUnit.SECONDS))
            .setResponseTimeout(Timeout.of(TIMEOUT_SEC, TimeUnit.SECONDS))
            .build();

        try (CloseableHttpClient client = HttpClients.custom()
                .setDefaultRequestConfig(config).build()) {

            HttpPost request = new HttpPost(url);
            request.setHeader("Authorization", "Bearer " + apiKey);
            request.setHeader("Content-Type", "application/json");
            request.setHeader("Accept", "application/json");
            request.setEntity(new StringEntity(gson.toJson(body)));

            return client.execute(request, response -> {
                String responseBody = EntityUtils.toString(response.getEntity());
                if (response.getCode() >= 400) {
                    errors.add(String.format("Climatiq %s → HTTP %d", activityId, response.getCode()));
                    return null;
                }
                JsonObject data = gson.fromJson(responseBody, JsonObject.class);
                if (data.has("co2e") && !data.get("co2e").isJsonNull()) {
                    // API returns kgCO2e → convert to tCO2e
                    return data.get("co2e").getAsDouble() / 1000.0;
                }
                errors.add("Climatiq " + activityId + " → no co2e in response");
                return null;
            });

        } catch (Exception e) {
            errors.add("Climatiq " + activityId + " failed: " + e.getMessage());
            return null;
        }
    }

    private Double estimateWithCandidates(List<String> ids, Map<String, Object> params, List<String> errors) {
        for (String id : ids) {
            Double result = estimateSingle(id, params, errors);
            if (result != null) return result;
        }
        return null;
    }

    // ── Activity ID resolvers ─────────────────────────────────────────────

    private List<String> resolveTransportIds(String type) {
        if (type == null) type = "";
        return switch (type.toLowerCase().trim()) {
            case "train"                      -> List.of("freight_train-route_type_na-fuel_source_na");
            case "bateau", "ship", "maritime" -> List.of("sea_freight-route_type_na");
            case "avion", "air"               -> List.of("air_freight-route_type_domestic");
            default -> List.of(
                "freight_vehicle-vehicle_type_commercial_truck-fuel_source_na-vehicle_weight_na-percentage_load_na",
                "freight_vehicle-vehicle_type_straight_truck-fuel_source_na-vehicle_weight_na-percentage_load_na-load_type_na-distance_uplift_na"
            );
        };
    }

    private List<String> resolveMaterialIds(String type) {
        if (type == null) type = "";
        String m = type.toLowerCase();
        if (m.contains("acier") || m.contains("steel"))       return List.of("metals-type_steel_engineering_steel");
        if (m.contains("aluminium") || m.contains("aluminum")) return List.of("metals-type_aluminium_primary_production");
        if (m.contains("bois") || m.contains("wood"))          return List.of("wood_products-type_sawn_timber");
        if (m.contains("plastique") || m.contains("plastic"))  return List.of("plastics-type_average_plastics");
        return List.of("construction_materials-type_cement");
    }

    // ── Fallback heuristics ───────────────────────────────────────────────

    private CarbonMetricResult fallback(ProjectData project, List<String> errors) {
        double s1 = fallbackScope1(project);
        double s2 = fallbackScope2(project);
        double s3 = fallbackScope3(project);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(r3(s1));
        result.setScope2Tco2(r3(s2));
        result.setScope3Tco2(r3(s3));
        result.setTotalTco2(r3(s1 + s2 + s3));
        result.setMethod("GL_HEURISTIC_CLIMATIQ_COMPAT_V1");
        result.setProviderErrors(errors);
        return result;
    }

    private double fallbackScope1(ProjectData p) {
        double transport = pos(p.getDistanceTransport());
        double waste     = pos(p.getDechetsGeneres());
        return (transport * FACTOR_TRANSPORT) + (waste * FACTOR_WASTE);
    }

    private double fallbackScope2(ProjectData p) {
        double energy = pos(p.getConsommationEnergie());
        String unit   = p.getUniteEnergie() != null ? p.getUniteEnergie() : "kWh";
        // Mirror Python _autoscale_energy: if energy < 10 000 treat as MWh → convert to kWh once
        double energyKwh;
        if (energy > 0 && energy < 10_000 && "kwh".equalsIgnoreCase(unit)) {
            energyKwh = energy * 1_000.0;  // MWh → kWh
        } else {
            energyKwh = toEnergyKwh(energy, unit);  // normal unit conversion
        }
        return energyKwh * FACTOR_ENERGY;
    }

    private double fallbackScope3(ProjectData p) {
        return pos(p.getQuantiteMateriau()) * FACTOR_MATERIAL;
    }

    // ── Utilities ─────────────────────────────────────────────────────────

    private double toEnergyKwh(double value, String unit) {
        if (value <= 0) return 0.0;
        return switch (unit.toLowerCase().trim()) {
            case "mwh" -> value * 1_000.0;
            case "gwh" -> value * 1_000_000.0;
            case "wh"  -> value / 1_000.0;
            default    -> value;
        };
    }

    private double pos(Double v) { return (v != null && v > 0) ? v : 0.0; }
    private double r3(double v)  { return Math.round(v * 1000.0) / 1000.0; }
}

package Services;

import Models.dto.CarbonMetricResult;
import Models.dto.ProjectData;
import Utils.EnvLoader;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.apache.hc.client5.http.classic.methods.HttpPost;
import org.apache.hc.client5.http.config.RequestConfig;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.core5.http.io.entity.EntityUtils;
import org.apache.hc.core5.http.io.entity.StringEntity;
import org.apache.hc.core5.util.Timeout;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Climatiq API Client
 *
 * POST https://api.climatiq.io/data/v1/estimate
 * Returns scope1, scope2, scope3 in kgCO2e → converted to tCO2e
 *
 * Fallback emission factors (when API unavailable):
 *   Transport: 0.0001 tCO2e/km
 *   Waste:     0.5    tCO2e/tonne
 *   Energy:    0.0005 tCO2e/kWh
 *   Material:  2.0    tCO2e/tonne
 */
public class ClimatiqApiClient {

    private static final String BASE_URL     = "https://api.climatiq.io";
    private static final String DATA_VERSION = "^32";  // wildcard — matches latest 32.x
    private static final int    TIMEOUT_SEC  = 15;

    // Fallback factors (match the original PHP logic and units)
    // transport: tCO2e/km, waste: tCO2e/kg, energy: tCO2e/kWh, material: tCO2e/kg
    private static final double FACTOR_TRANSPORT = 0.00008;
    private static final double FACTOR_WASTE     = 0.00070;
    private static final double FACTOR_ENERGY    = 0.00045;
    private static final double FACTOR_MATERIAL  = 0.00120;

    private final String apiKey;
    private final Gson   gson = new Gson();

    public ClimatiqApiClient() {
        this.apiKey = EnvLoader.get("CLIMATIQ_API_KEY", "");
        if (apiKey.isBlank()) {
            System.err.println("[Climatiq] CLIMATIQ_API_KEY not set — will use fallback heuristics");
        } else {
            System.out.println("[Climatiq] API client initialized");
        }
    }

    // ── Main entry point ──────────────────────────────────────────────────

    public CarbonMetricResult estimateProjectEmissions(ProjectData project) {
        List<String> errors = new ArrayList<>();

        if (apiKey.isBlank()) {
            return fallback(project, errors);
        }

        // Normalize once, then reuse the same units everywhere.
        double energyKwh   = toEnergyKwh(pos(project.getConsommationEnergie()), project.getUniteEnergie());
        double distanceKm   = pos(project.getDistanceTransport());
        double materialTon  = toMaterialTonnes(project.getQuantiteMateriau());

        System.out.printf("[Climatiq] Normalized inputs: energy=%.3f kWh, distance=%.3f km, material=%.3f t%n",
            energyKwh, distanceKm, materialTon);

        Double scope1 = null, scope2 = null, scope3 = null;

        // Scope 1: Transport
        if (distanceKm > 0 && materialTon > 0) {
            scope1 = estimateWithCandidates(
                resolveTransportIds(project.getTypeTransport()),
                Map.of("weight", materialTon, "weight_unit", "t",
                       "distance", distanceKm, "distance_unit", "km"),
                errors);
        }

        // Scope 2: Energy
        if (energyKwh > 0) {
            scope2 = estimateWithCandidates(
                List.of(
                    "electricity-supply_grid-source_residual_mix",
                    "electricity-supply_grid-source_supplier_mix",
                    "electricity-supply_grid-source_geothermal_energy"
                ),
                Map.of("energy", energyKwh, "energy_unit", "kWh"),
                errors);
        }

        // Scope 3: Materials
        if (materialTon > 0) {
            scope3 = estimateWithCandidates(
                resolveMaterialIds(project.getTypeMateriau()),
                Map.of("weight", materialTon, "weight_unit", "t"),
                errors);
        }

        // If all scopes failed, use fallback
        if (scope1 == null && scope2 == null && scope3 == null) {
            System.err.println("[Climatiq] All API calls failed — using fallback");
            return fallback(project, errors);
        }

        double s1 = scope1 != null ? scope1 : fallbackScope1(project);
        double s2 = scope2 != null ? scope2 : fallbackScope2(project);
        double s3 = scope3 != null ? scope3 : fallbackScope3(project);
        double total = r3(s1 + s2 + s3);

        // Guardrail: only revert to fallback if Climatiq result is > 10× fallback
        // (catches clearly wrong API responses, not just higher-precision results)
        double fb = r3(fallbackScope1(project) + fallbackScope2(project) + fallbackScope3(project));
        if (fb > 0.1 && total > fb * 10.0) {
            System.err.printf("[Climatiq] Guardrail: API=%.3f > 10× fallback=%.3f — reverting%n", total, fb);
            return fallback(project, errors);
        }

        System.out.printf("[Climatiq] ✓ API result: scope1=%.3f scope2=%.3f scope3=%.3f total=%.3f tCO2e%n",
            s1, s2, s3, total);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(r3(s1));
        result.setScope2Tco2(r3(s2));
        result.setScope3Tco2(r3(s3));
        result.setTotalTco2(total);
        result.setMethod("CLIMATIQ_API_V1_ESTIMATE");
        result.setProviderErrors(errors);
        return result;
    }

    // ── Single API call ───────────────────────────────────────────────────

    private Double estimateSingle(String activityId, Map<String, Object> params, List<String> errors) {
        String url = BASE_URL + "/data/v1/estimate";

        JsonObject emissionFactor = new JsonObject();
        emissionFactor.addProperty("activity_id", activityId);
        emissionFactor.addProperty("data_version", DATA_VERSION);

        JsonObject body = new JsonObject();
        body.add("emission_factor", emissionFactor);
        body.add("parameters", gson.toJsonTree(params));

        RequestConfig config = RequestConfig.custom()
            .setConnectionRequestTimeout(Timeout.of(TIMEOUT_SEC, TimeUnit.SECONDS))
            .setResponseTimeout(Timeout.of(TIMEOUT_SEC, TimeUnit.SECONDS))
            .build();

        try (CloseableHttpClient client = HttpClients.custom()
                .setDefaultRequestConfig(config).build()) {

            HttpPost request = new HttpPost(url);
            request.setHeader("Authorization", "Bearer " + apiKey);
            request.setHeader("Content-Type", "application/json");
            request.setHeader("Accept", "application/json");
            request.setEntity(new StringEntity(gson.toJson(body)));

            return client.execute(request, response -> {
                String responseBody = EntityUtils.toString(response.getEntity());
                if (response.getCode() >= 400) {
                    errors.add(String.format("Climatiq %s → HTTP %d", activityId, response.getCode()));
                    return null;
                }
                JsonObject data = gson.fromJson(responseBody, JsonObject.class);
                if (data.has("co2e") && !data.get("co2e").isJsonNull()) {
                    // API returns kgCO2e → convert to tCO2e
                    return data.get("co2e").getAsDouble() / 1000.0;
                }
                errors.add("Climatiq " + activityId + " → no co2e in response");
                return null;
            });

        } catch (Exception e) {
            errors.add("Climatiq " + activityId + " failed: " + e.getMessage());
            return null;
        }
    }

    private Double estimateWithCandidates(List<String> ids, Map<String, Object> params, List<String> errors) {
        for (String id : ids) {
            Double result = estimateSingle(id, params, errors);
            if (result != null) return result;
        }
        return null;
    }

    // ── Activity ID resolvers ─────────────────────────────────────────────

    private List<String> resolveTransportIds(String type) {
        if (type == null) type = "";
        return switch (type.toLowerCase().trim()) {
            case "train"                      -> List.of("freight_train-route_type_na-fuel_source_na");
            case "bateau", "ship", "maritime" -> List.of("sea_freight-route_type_na");
            case "avion", "air"               -> List.of("air_freight-route_type_domestic");
            default -> List.of(
                "freight_vehicle-vehicle_type_commercial_truck-fuel_source_na-vehicle_weight_na-percentage_load_na",
                "freight_vehicle-vehicle_type_straight_truck-fuel_source_na-vehicle_weight_na-percentage_load_na-load_type_na-distance_uplift_na"
            );
        };
    }

    private List<String> resolveMaterialIds(String type) {
        if (type == null) type = "";
        String m = type.toLowerCase();
        if (m.contains("acier") || m.contains("steel"))       return List.of("metals-type_steel_engineering_steel");
        if (m.contains("aluminium") || m.contains("aluminum")) return List.of("metals-type_aluminium_primary_production");
        if (m.contains("bois") || m.contains("wood"))          return List.of("wood_products-type_sawn_timber");
        if (m.contains("plastique") || m.contains("plastic"))  return List.of("plastics-type_average_plastics");
        return List.of("construction_materials-type_cement");
    }

    // ── Fallback heuristics ───────────────────────────────────────────────

    private CarbonMetricResult fallback(ProjectData project, List<String> errors) {
        double s1 = fallbackScope1(project);
        double s2 = fallbackScope2(project);
        double s3 = fallbackScope3(project);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(r3(s1));
        result.setScope2Tco2(r3(s2));
        result.setScope3Tco2(r3(s3));
        result.setTotalTco2(r3(s1 + s2 + s3));
        result.setMethod("GL_HEURISTIC_CLIMATIQ_COMPAT_V1");
        result.setProviderErrors(errors);
        return result;
    }

    private double fallbackScope1(ProjectData p) {
        double transport = pos(p.getDistanceTransport());
        double waste     = pos(p.getDechetsGeneres());
        return (transport * FACTOR_TRANSPORT) + (waste * FACTOR_WASTE);
    }

    private double fallbackScope2(ProjectData p) {
        double energyKwh = toEnergyKwh(pos(p.getConsommationEnergie()), p.getUniteEnergie());
        return energyKwh * FACTOR_ENERGY;
    }

    private double fallbackScope3(ProjectData p) {
        return toMaterialTonnes(p.getQuantiteMateriau()) * 1000.0 * FACTOR_MATERIAL;
    }

    // ── Utilities ─────────────────────────────────────────────────────────

    private double toEnergyKwh(double value, String unit) {
        if (value <= 0) return 0.0;
        String normalized = unit != null ? unit.toLowerCase().trim() : "kwh";
        return switch (normalized) {
            case "mwh" -> value * 1_000.0;
            case "gwh" -> value * 1_000_000.0;
            case "wh"  -> value / 1_000.0;
            default    -> value;
        };
    }

    /**
     * The project quantity is stored in kilograms in the current database flow.
     * Climatiq material factors expect tonnes, so convert once here.
     */
    private double toMaterialTonnes(Double value) {
        double kg = pos(value);
        return kg / 1_000.0;
    }

    private double pos(Double v) { return (v != null && v > 0) ? v : 0.0; }
    private double r3(double v)  { return Math.round(v * 1000.0) / 1000.0; }
}

package Services;

import DataBase.MyConnection;
import Models.*;
import Models.dto.*;

import java.sql.*;
import java.time.LocalDate;
import java.util.List;

/**
 * Expert Workflow Service — main ML pipeline orchestrator.
 *
 * Pipeline:
 *   1. Extract ProjectData from Projet entity
 *   2. Climatiq API → carbon metrics (scope1/2/3) with fallback heuristics
 *   3. ML API → ESG score + fraud assessment (with heuristic fallback)
 *   4. Persist results to DB (carbon_metric, ml_predictions, ml_fraud_assessment)
 *   5. Green credit dispatch (eligibility + calculation)
 *   6. Update projet table (fraud fields, green credit fields)
 *   7. Return AnalysisResult
 */
public class ExpertWorkflowService {

    // Fallback emission factors
    private static final double FACTOR_TRANSPORT = 0.0001;
    private static final double FACTOR_WASTE     = 0.5;
    private static final double FACTOR_ENERGY    = 0.0005;
    private static final double FACTOR_MATERIAL  = 2.0;

    private final ProjetService           projetService;
    private final ClimatiqApiClient       climatiqClient;
    private final MlApiClient             mlApiClient;
    private final BaselineEmissionService baselineService;
    private final EligibilityCheckService eligibilityService;

    public ExpertWorkflowService() {
        this.projetService      = new ProjetService();
        this.climatiqClient     = new ClimatiqApiClient();
        this.mlApiClient        = new MlApiClient();
        this.baselineService    = new BaselineEmissionService();
        this.eligibilityService = new EligibilityCheckService();
    }

    // ══════════════════════════════════════════════════════════════════════
    // MAIN ENTRY POINT
    // ══════════════════════════════════════════════════════════════════════

    /**
     * Run the full ML analysis pipeline for a project.
     *
     * @param projectId  ID of the project to analyze
     * @param expertId   ID of the expert running the analysis
     * @return AnalysisResult with all computed values
     */
    public AnalysisResult runAnalysis(int projectId, int expertId) {
        System.out.println("[ExpertWorkflow] Starting analysis for project " + projectId);

        Projet project = projetService.getById(projectId);
        if (project == null) throw new IllegalArgumentException("Project not found: " + projectId);

        ProjectData data = ProjectData.from(project);

        // ── Step 1: Carbon metrics ────────────────────────────────────────
        CarbonMetricResult carbonMetric = estimateAndStoreCarbonMetric(projectId, data);
        System.out.printf("[ExpertWorkflow] Carbon: scope1=%.3f scope2=%.3f scope3=%.3f total=%.3f tCO2e%n",
            orZero(carbonMetric.getScope1Tco2()),
            orZero(carbonMetric.getScope2Tco2()),
            orZero(carbonMetric.getScope3Tco2()),
            orZero(carbonMetric.getTotalTco2()));

        // ── Step 2: Set total_tco2 for ML input ───────────────────────────
        data.setTotalTco2(carbonMetric.getTotalTco2());

        // ── Step 3: ML prediction + fraud ─────────────────────────────────
        MlPredictionResult   mlPrediction;
        FraudAssessmentResult fraudAssessment;

        boolean pythonAvailable = mlApiClient.isHealthy();
        if (pythonAvailable) {
            try {
                BothPredictionResult both = mlApiClient.predictBoth(data);
                mlPrediction   = both.getEsg();
                fraudAssessment = both.getFraud();
                System.out.println("[ExpertWorkflow] ML from Python API");
            } catch (Exception e) {
                System.err.println("[ExpertWorkflow] ML API failed, using heuristics: " + e.getMessage());
                mlPrediction   = heuristicMlPrediction(carbonMetric);
                fraudAssessment = heuristicFraudAssessment(data, carbonMetric);
            }
        } else {
            System.out.println("[ExpertWorkflow] ML API unavailable, using heuristics");
            mlPrediction   = heuristicMlPrediction(carbonMetric);
            fraudAssessment = heuristicFraudAssessment(data, carbonMetric);
        }

        System.out.printf("[ExpertWorkflow] ML: ESG=%d credibility=%d risk=%s decision=%s%n",
            mlPrediction.getPredictedEsgScore(),
            mlPrediction.getCredibilityScore(),
            mlPrediction.getCarbonRisk(),
            mlPrediction.getDecision());

        System.out.printf("[ExpertWorkflow] Fraud: risk=%.4f anomaly=%.4f flag=%b%n",
            orZero(fraudAssessment.getFraudRiskScore()),
            orZero(fraudAssessment.getFraudAnomalyScore()),
            fraudAssessment.isFraudFlag());

        // ── Step 4: Persist ML results ────────────────────────────────────
        storeMlPrediction(projectId, mlPrediction, expertId);
        storeFraudAssessment(projectId, fraudAssessment);
        updateProjectFraudFields(projectId, fraudAssessment);

        // ── Step 5: Green credit dispatch ─────────────────────────────────
        GreenCreditResult greenCredit = computeGreenCredits(
            project, carbonMetric, fraudAssessment, mlPrediction);

        updateProjectGreenCreditFields(projectId, greenCredit, carbonMetric);

        System.out.printf("[ExpertWorkflow] Credits: eligible=%b avoided=%.3f credits=%.3f%n",
            greenCredit.isEligible(),
            orZero(greenCredit.getAvoidedTco2()),
            orZero(greenCredit.getDispatchedCredits()));

        // ── Step 6: Build result ──────────────────────────────────────────
        AnalysisResult result = new AnalysisResult();
        result.setCarbonMetric(carbonMetric);
        result.setMlPrediction(mlPrediction);
        result.setFraudAssessment(fraudAssessment);
        result.setGreenCreditDispatch(greenCredit);

        System.out.println("[ExpertWorkflow] Analysis complete: decision=" + result.getDecision());
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 1: CARBON METRIC
    // ══════════════════════════════════════════════════════════════════════

    private CarbonMetricResult estimateAndStoreCarbonMetric(int projectId, ProjectData data) {
        // ── Step 0: Check if there's already a valid carbon_metric in the DB
        //    (e.g., previously computed by the web/Symfony via Climatiq API).
        //    Prefer those stored values over recalculating with heuristics.
        CarbonMetricResult existing = readLatestCarbonMetric(projectId);
        if (existing != null) {
            System.out.printf("[ExpertWorkflow] Using stored carbon_metric for project %d: total=%.3f tCO2e%n",
                projectId, orZero(existing.getTotalTco2()));
            return existing;
        }

        // Try Climatiq API
        CarbonMetricResult result;
        try {
            result = climatiqClient.estimateProjectEmissions(data);
        } catch (Exception e) {
            System.err.println("[ExpertWorkflow] Climatiq failed: " + e.getMessage());
            result = fallbackCarbonMetric(data);
        }

        // Compute data quality score
        double quality = computeDataQualityScore(data, result.getProviderErrors());
        result.setDataQualityScore(quality);

        // Persist to carbon_metric table
        String sql = "INSERT INTO carbon_metric " +
                     "(project_id, metric_date, scope1_tco2, scope2_tco2, scope3_tco2, " +
                     " total_tco2, method, data_quality_score) " +
                     "VALUES (?, CURDATE(), ?, ?, ?, ?, ?, ?)";

        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setDoubleOrNull(ps, 2, result.getScope1Tco2());
            setDoubleOrNull(ps, 3, result.getScope2Tco2());
            setDoubleOrNull(ps, 4, result.getScope3Tco2());
            setDoubleOrNull(ps, 5, result.getTotalTco2());
            ps.setString(6, result.getMethod());
            setDoubleOrNull(ps, 7, result.getDataQualityScore());
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store carbon_metric: " + e.getMessage());
        }

        return result;
    }

    /**
     * Read the most recent carbon_metric row already stored for a project.
     * Returns null if none found or if the stored total is zero.
     */
    private CarbonMetricResult readLatestCarbonMetric(int projectId) {
        String sql = "SELECT scope1_tco2, scope2_tco2, scope3_tco2, total_tco2, method, data_quality_score " +
                     "FROM carbon_metric WHERE project_id = ? " +
                     "ORDER BY metric_date DESC, id DESC LIMIT 1";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    double total = rs.getDouble("total_tco2");
                    if (!rs.wasNull() && total > 0) {
                        CarbonMetricResult r = new CarbonMetricResult();
                        r.setScope1Tco2(nullableDouble(rs, "scope1_tco2"));
                        r.setScope2Tco2(nullableDouble(rs, "scope2_tco2"));
                        r.setScope3Tco2(nullableDouble(rs, "scope3_tco2"));
                        r.setTotalTco2(total);
                        r.setMethod(rs.getString("method"));
                        double dq = rs.getDouble("data_quality_score");
                        r.setDataQualityScore(rs.wasNull() ? 70.0 : dq);
                        return r;
                    }
                }
            }
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] readLatestCarbonMetric failed: " + e.getMessage());
        }
        return null;
    }

    private Double nullableDouble(ResultSet rs, String col) throws SQLException {
        double v = rs.getDouble(col);
        return rs.wasNull() ? null : v;
    }

    private CarbonMetricResult fallbackCarbonMetric(ProjectData data) {
        double energy    = pos(data.getConsommationEnergie());
        double transport = pos(data.getDistanceTransport());
        double material  = pos(data.getQuantiteMateriau());
        double waste     = pos(data.getDechetsGeneres());

        // Mirror Python _autoscale_energy: if energy < 10 000 treat value as MWh → convert once to kWh
        String unit = data.getUniteEnergie() != null ? data.getUniteEnergie() : "kWh";
        double energyKwh;
        if (energy > 0 && energy < 10_000 && "kwh".equalsIgnoreCase(unit)) {
            energyKwh = energy * 1_000.0;  // treat as MWh → kWh
        } else {
            energyKwh = energy;  // already in kWh or another unit already large
        }

        double s1 = r3((transport * FACTOR_TRANSPORT) + (waste * FACTOR_WASTE));
        double s2 = r3(energyKwh * FACTOR_ENERGY);
        double s3 = r3(material * FACTOR_MATERIAL);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(s1);
        result.setScope2Tco2(s2);
        result.setScope3Tco2(s3);
        result.setTotalTco2(r3(s1 + s2 + s3));
        result.setMethod("GL_HEURISTIC_CLIMATIQ_COMPAT_V1");
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 2: HEURISTIC ML FALLBACK
    // Mirrors Python predict_model.py logic exactly
    // ══════════════════════════════════════════════════════════════════════

    private MlPredictionResult heuristicMlPrediction(CarbonMetricResult carbon) {
        double totalTco2 = orZero(carbon.getTotalTco2());
        double quality   = orZero(carbon.getDataQualityScore(), 50.0);

        // ESG score formula (mirrors Python)
        double score = Math.max(0, Math.min(10, 9.5 - (totalTco2 / 25.0)));
        int esgScore = (int) Math.round(score);

        // Credibility
        int credibility = (int) Math.round(Math.max(0, Math.min(100, quality)));

        // Carbon risk
        String carbonRisk;
        if (totalTco2 >= 50) carbonRisk = "HIGH";
        else if (totalTco2 >= 20) carbonRisk = "MEDIUM";
        else carbonRisk = "LOW";

        // Decision
        String decision;
        if ("HIGH".equals(carbonRisk)) {
            decision = "REJECTED";
        } else if (esgScore >= 7 && "LOW".equals(carbonRisk)) {
            decision = "APPROVED";
        } else if (esgScore >= 5) {
            decision = "REVISION_REQUIRED";
        } else {
            decision = "REJECTED";
        }

        MlPredictionResult result = new MlPredictionResult();
        result.setPredictedEsgScore(esgScore);
        result.setCredibilityScore(credibility);
        result.setCarbonRisk(carbonRisk);
        result.setDecision(decision);
        result.setModelVersion("java-heuristic-v1");
        return result;
    }

    private FraudAssessmentResult heuristicFraudAssessment(ProjectData data, CarbonMetricResult carbon) {
        double energy    = pos(data.getConsommationEnergie());
        double transport = pos(data.getDistanceTransport());
        double material  = pos(data.getQuantiteMateriau());
        double declared  = pos(data.getEmissionsEstimees());
        double computed  = orZero(carbon.getTotalTco2());

        int missingNumeric  = (energy == 0 ? 1 : 0) + (declared == 0 ? 1 : 0);
        int missingOptional = (transport == 0 ? 1 : 0) + (material == 0 ? 1 : 0);

        double distPerMat = material > 0 ? transport / material : 0.0;
        double emPerEn    = energy   > 0 ? declared  / energy   : 0.0;
        double gapBase    = Math.max(Math.max(computed, declared), 1.0);
        double carbonGap  = Math.abs(declared - computed) / gapBase;

        double risk = 0.0;
        risk += Math.min(0.10, missingNumeric  * 0.08);
        risk += Math.min(0.06, missingOptional * 0.015);
        risk += Math.min(0.10, carbonGap       * 0.10);

        if (computed >= 80)      risk += 0.25;
        else if (computed >= 50) risk += 0.12;

        if (distPerMat > 14)      risk += 0.12;
        else if (distPerMat > 10) risk += 0.06;

        if (emPerEn > 0.06)      risk += 0.10;
        else if (emPerEn > 0.04) risk += 0.05;

        risk = Math.max(0.0, Math.min(1.0, risk));
        double anomaly = Math.max(0.0, Math.min(3.0, 1.05 * risk));

        boolean hardSignal = missingNumeric >= 2 || distPerMat > 20 || emPerEn > 0.08 || computed >= 80;
        boolean fraudFlag  = hardSignal || risk >= 0.65;

        FraudAssessmentResult result = new FraudAssessmentResult();
        result.setFraudRiskScore(r4(risk));
        result.setFraudAnomalyScore(r4(anomaly));
        result.setFraudFlag(fraudFlag);
        result.setModelVersion("java-heuristic-v1");
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 3: GREEN CREDIT DISPATCH
    // ══════════════════════════════════════════════════════════════════════

    private GreenCreditResult computeGreenCredits(Projet project,
                                                   CarbonMetricResult carbon,
                                                   FraudAssessmentResult fraud,
                                                   MlPredictionResult ml) {
        double actualTco2   = orZero(carbon.getTotalTco2());
        double quality      = orZero(carbon.getDataQualityScore(), 50.0);
        double avoidedTco2  = baselineService.calculateAvoided(ProjectData.from(project), actualTco2);
        double fraudRisk    = orZero(fraud.getFraudRiskScore());
        int    esgScore     = ml.getPredictedEsgScore() != null ? ml.getPredictedEsgScore() : 0;

        // Eligibility check
        EligibilityCheckService.EligibilityResult eligibility =
            eligibilityService.check(project.getStatutEvaluation(), avoidedTco2, quality, fraud);

        if (!eligibility.eligible()) {
            GreenCreditResult r = GreenCreditResult.notEligible(eligibility.reason());
            r.setBaselineTco2(baselineService.calculateBaseline(ProjectData.from(project)));
            r.setActualTco2(actualTco2);
            r.setAvoidedTco2(avoidedTco2);
            return r;
        }

        // Calculate credits
        double credibilityFactor = eligibilityService.credibilityFactor(quality, fraudRisk, avoidedTco2);
        double esgMultiplier     = eligibilityService.esgMultiplier(esgScore);
        double credits           = r3(avoidedTco2 * credibilityFactor * esgMultiplier);

        String formula = String.format("%.3f tCO2e × %.2f credibility × %.2f ESG = %.3f credits",
            avoidedTco2, credibilityFactor, esgMultiplier, credits);

        String badge = credits > 10 ? "High Impact" : credits > 1 ? "Eligible" : "Low Impact";

        GreenCreditResult result = new GreenCreditResult();
        result.setBaselineTco2(baselineService.calculateBaseline(ProjectData.from(project)));
        result.setActualTco2(actualTco2);
        result.setAvoidedTco2(avoidedTco2);
        result.setDispatchedCredits(credits);
        result.setCredibilityFactor(credibilityFactor);
        result.setEsgMultiplier(esgMultiplier);
        result.setEligible(true);
        result.setStatusBadge(badge);
        result.setFormula(formula);
        result.setExplanation(eligibility.reason());
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // DB PERSISTENCE
    // ══════════════════════════════════════════════════════════════════════

    private void storeMlPrediction(int projectId, MlPredictionResult ml, int expertId) {
        String sql = "INSERT INTO ml_predictions " +
                     "(project_id, predicted_esg_score, credibility_score, carbon_risk, " +
                     " decision, recommendations, model_version, created_by_user_id, created_at) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW())";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setIntOrNull(ps, 2, ml.getPredictedEsgScore());
            setIntOrNull(ps, 3, ml.getCredibilityScore());
            ps.setString(4, ml.getCarbonRisk());
            ps.setString(5, ml.getDecision());
            ps.setString(6, ml.getRecommendations());
            ps.setString(7, ml.getModelVersion());
            ps.setInt(8, expertId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store ml_predictions: " + e.getMessage());
        }
    }

    private void storeFraudAssessment(int projectId, FraudAssessmentResult fraud) {
        String sql = "INSERT INTO ml_fraud_assessment " +
                     "(project_id, fraud_risk_score, anomaly_score, fraud_flag, " +
                     " suspicious_features, model_version, created_at) " +
                     "VALUES (?, ?, ?, ?, ?, ?, NOW())";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setDoubleOrNull(ps, 2, fraud.getFraudRiskScore());
            setDoubleOrNull(ps, 3, fraud.getFraudAnomalyScore());
            ps.setBoolean(4, fraud.isFraudFlag());
            ps.setString(5, fraud.getFraudReasons() != null
                ? String.join(" | ", fraud.getFraudReasons()) : null);
            ps.setString(6, fraud.getModelVersion());
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store ml_fraud_assessment: " + e.getMessage());
        }
    }

    private void updateProjectFraudFields(int projectId, FraudAssessmentResult fraud) {
        String sql = "UPDATE projet SET " +
                     "fraud_risk_score=?, fraud_anomaly_score=?, fraud_flag=?, " +
                     "fraud_reasons=?, fraud_scored_at=NOW() WHERE id=?";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            setDoubleOrNull(ps, 1, fraud.getFraudRiskScore());
            setDoubleOrNull(ps, 2, fraud.getFraudAnomalyScore());
            ps.setBoolean(3, fraud.isFraudFlag());
            ps.setString(4, fraud.getFraudReasons() != null
                ? String.join(" | ", fraud.getFraudReasons()) : null);
            ps.setInt(5, projectId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to update projet fraud fields: " + e.getMessage());
        }
    }

    private void updateProjectGreenCreditFields(int projectId,
                                                 GreenCreditResult credit,
                                                 CarbonMetricResult carbon) {
        String sql = "UPDATE projet SET " +
                     "baseline_tco2=?, actual_tco2=?, avoided_tco2=?, " +
                     "dispatched_green_credits=?, green_credit_credibility_factor=?, " +
                     "green_credit_esg_multiplier=?, green_credit_dispatch_status=?, " +
                     "green_credit_status_badge=?, green_credit_formula=?, " +
                     "green_credit_last_computed_at=NOW() WHERE id=?";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            setDoubleOrNull(ps, 1, credit.getBaselineTco2());
            setDoubleOrNull(ps, 2, credit.getActualTco2());
            setDoubleOrNull(ps, 3, credit.getAvoidedTco2());
            setDoubleOrNull(ps, 4, credit.getDispatchedCredits());
            setDoubleOrNull(ps, 5, credit.getCredibilityFactor());
            setDoubleOrNull(ps, 6, credit.getEsgMultiplier());
            ps.setString(7, credit.isEligible() ? "DISPATCHED" : "NOT_ELIGIBLE");
            ps.setString(8, credit.getStatusBadge());
            ps.setString(9, credit.getFormula());
            ps.setInt(10, projectId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to update projet green credit fields: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // DATA QUALITY SCORE
    // ══════════════════════════════════════════════════════════════════════

    private double computeDataQualityScore(ProjectData data, List<String> errors) {
        int score = 100;

        // Deduct for missing fields
        if (pos(data.getConsommationEnergie()) == 0) score -= 15;
        if (pos(data.getDistanceTransport())   == 0) score -= 10;
        if (pos(data.getQuantiteMateriau())    == 0) score -= 10;
        if (pos(data.getDechetsGeneres())      == 0) score -= 5;
        if (pos(data.getEmissionsEstimees())   == 0) score -= 10;
        if (data.getSecteur()    == null || data.getSecteur().isBlank())    score -= 5;
        if (data.getLocalisation() == null || data.getLocalisation().isBlank()) score -= 5;

        // Deduct for API errors
        if (errors != null) score -= Math.min(20, errors.size() * 5);

        return Math.max(0, Math.min(100, score));
    }

    // ══════════════════════════════════════════════════════════════════════
    // UTILITIES
    // ══════════════════════════════════════════════════════════════════════

    private double pos(Double v)                    { return (v != null && v > 0) ? v : 0.0; }
    private double orZero(Double v)                 { return v != null ? v : 0.0; }
    private double orZero(Double v, double def)     { return v != null ? v : def; }
    private double r3(double v)                     { return Math.round(v * 1000.0) / 1000.0; }
    private double r4(double v)                     { return Math.round(v * 10000.0) / 10000.0; }

    private void setDoubleOrNull(PreparedStatement ps, int idx, Double v) throws SQLException {
        if (v == null) ps.setNull(idx, Types.DOUBLE);
        else           ps.setDouble(idx, v);
    }

    private void setIntOrNull(PreparedStatement ps, int idx, Integer v) throws SQLException {
        if (v == null) ps.setNull(idx, Types.INTEGER);
        else           ps.setInt(idx, v);
    }
}

package Services;

import DataBase.MyConnection;
import Models.*;
import Models.dto.*;

import java.sql.*;
import java.time.LocalDate;
import java.util.List;

/**
 * Expert Workflow Service — main ML pipeline orchestrator.
 *
 * Pipeline:
 *   1. Extract ProjectData from Projet entity
 *   2. Climatiq API → carbon metrics (scope1/2/3) with fallback heuristics
 *   3. ML API → ESG score + fraud assessment (with heuristic fallback)
 *   4. Persist results to DB (carbon_metric, ml_predictions, ml_fraud_assessment)
 *   5. Green credit dispatch (eligibility + calculation)
 *   6. Update projet table (fraud fields, green credit fields)
 *   7. Return AnalysisResult
 */
public class ExpertWorkflowService {

    // Fallback emission factors (match the original PHP logic and units)
    // transport: tCO2e/km, waste: tCO2e/kg, energy: tCO2e/kWh, material: tCO2e/kg
    private static final double FACTOR_TRANSPORT = 0.00008;
    private static final double FACTOR_WASTE     = 0.00070;
    private static final double FACTOR_ENERGY    = 0.00045;
    private static final double FACTOR_MATERIAL  = 0.00120;

    private final ProjetService           projetService;
    private final ClimatiqApiClient       climatiqClient;
    private final MlApiClient             mlApiClient;
    private final BaselineEmissionService baselineService;
    private final EligibilityCheckService eligibilityService;

    public ExpertWorkflowService() {
        this.projetService      = new ProjetService();
        this.climatiqClient     = new ClimatiqApiClient();
        this.mlApiClient        = new MlApiClient();
        this.baselineService    = new BaselineEmissionService();
        this.eligibilityService = new EligibilityCheckService();
    }

    // ══════════════════════════════════════════════════════════════════════
    // MAIN ENTRY POINT
    // ══════════════════════════════════════════════════════════════════════

    /**
     * Run the full ML analysis pipeline for a project.
     *
     * @param projectId  ID of the project to analyze
     * @param expertId   ID of the expert running the analysis
     * @return AnalysisResult with all computed values
     */
    public AnalysisResult runAnalysis(int projectId, int expertId) {
        System.out.println("[ExpertWorkflow] Starting analysis for project " + projectId);

        Projet project = projetService.getById(projectId);
        if (project == null) throw new IllegalArgumentException("Project not found: " + projectId);

        ProjectData data = ProjectData.from(project);

        // ── Step 1: Carbon metrics ────────────────────────────────────────
        CarbonMetricResult carbonMetric = estimateAndStoreCarbonMetric(projectId, data);
        System.out.printf("[ExpertWorkflow] Carbon: scope1=%.3f scope2=%.3f scope3=%.3f total=%.3f tCO2e%n",
            orZero(carbonMetric.getScope1Tco2()),
            orZero(carbonMetric.getScope2Tco2()),
            orZero(carbonMetric.getScope3Tco2()),
            orZero(carbonMetric.getTotalTco2()));

        // ── Step 2: Set total_tco2 for ML input ───────────────────────────
        data.setTotalTco2(carbonMetric.getTotalTco2());

        // ── Step 3: ML prediction + fraud ─────────────────────────────────
        MlPredictionResult   mlPrediction;
        FraudAssessmentResult fraudAssessment;

        boolean pythonAvailable = mlApiClient.isHealthy();
        if (pythonAvailable) {
            try {
                BothPredictionResult both = mlApiClient.predictBoth(data);
                mlPrediction   = both.getEsg();
                fraudAssessment = both.getFraud();
                System.out.println("[ExpertWorkflow] ML from Python API");
            } catch (Exception e) {
                System.err.println("[ExpertWorkflow] ML API failed, using heuristics: " + e.getMessage());
                mlPrediction   = heuristicMlPrediction(carbonMetric);
                fraudAssessment = heuristicFraudAssessment(data, carbonMetric);
            }
        } else {
            System.out.println("[ExpertWorkflow] ML API unavailable, using heuristics");
            mlPrediction   = heuristicMlPrediction(carbonMetric);
            fraudAssessment = heuristicFraudAssessment(data, carbonMetric);
        }

        System.out.printf("[ExpertWorkflow] ML: ESG=%d credibility=%d risk=%s decision=%s%n",
            mlPrediction.getPredictedEsgScore(),
            mlPrediction.getCredibilityScore(),
            mlPrediction.getCarbonRisk(),
            mlPrediction.getDecision());

        System.out.printf("[ExpertWorkflow] Fraud: risk=%.4f anomaly=%.4f flag=%b%n",
            orZero(fraudAssessment.getFraudRiskScore()),
            orZero(fraudAssessment.getFraudAnomalyScore()),
            fraudAssessment.isFraudFlag());

        // ── Step 4: Persist ML results ────────────────────────────────────
        storeMlPrediction(projectId, mlPrediction, expertId);
        storeFraudAssessment(projectId, fraudAssessment);
        updateProjectFraudFields(projectId, fraudAssessment);

        // ── Step 5: Green credit dispatch ─────────────────────────────────
        GreenCreditResult greenCredit = computeGreenCredits(
            project, carbonMetric, fraudAssessment, mlPrediction);

        updateProjectGreenCreditFields(projectId, greenCredit, carbonMetric);

        System.out.printf("[ExpertWorkflow] Credits: eligible=%b avoided=%.3f credits=%.3f%n",
            greenCredit.isEligible(),
            orZero(greenCredit.getAvoidedTco2()),
            orZero(greenCredit.getDispatchedCredits()));

        // ── Step 6: Build result ──────────────────────────────────────────
        AnalysisResult result = new AnalysisResult();
        result.setCarbonMetric(carbonMetric);
        result.setMlPrediction(mlPrediction);
        result.setFraudAssessment(fraudAssessment);
        result.setGreenCreditDispatch(greenCredit);

        System.out.println("[ExpertWorkflow] Analysis complete: decision=" + result.getDecision());
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 1: CARBON METRIC
    // ══════════════════════════════════════════════════════════════════════

    private CarbonMetricResult estimateAndStoreCarbonMetric(int projectId, ProjectData data) {
        // Always recompute with the normalized unit rules so old inflated rows
        // from previous runs do not keep being reused.
        CarbonMetricResult existing = readLatestCarbonMetric(projectId);
        if (existing != null) {
            System.out.printf("[ExpertWorkflow] Existing carbon_metric found for project %d (will refresh): total=%.3f tCO2e%n",
                projectId, orZero(existing.getTotalTco2()));
        }

        // Try Climatiq API
        CarbonMetricResult result;
        try {
            result = climatiqClient.estimateProjectEmissions(data);
        } catch (Exception e) {
            System.err.println("[ExpertWorkflow] Climatiq failed: " + e.getMessage());
            result = fallbackCarbonMetric(data);
        }

        // Compute data quality score
        double quality = computeDataQualityScore(data, result.getProviderErrors());
        result.setDataQualityScore(quality);

        // Persist to carbon_metric table
        String sql = "INSERT INTO carbon_metric " +
                     "(project_id, metric_date, scope1_tco2, scope2_tco2, scope3_tco2, " +
                     " total_tco2, method, data_quality_score) " +
                     "VALUES (?, CURDATE(), ?, ?, ?, ?, ?, ?)";

        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setDoubleOrNull(ps, 2, result.getScope1Tco2());
            setDoubleOrNull(ps, 3, result.getScope2Tco2());
            setDoubleOrNull(ps, 4, result.getScope3Tco2());
            setDoubleOrNull(ps, 5, result.getTotalTco2());
            ps.setString(6, result.getMethod());
            setDoubleOrNull(ps, 7, result.getDataQualityScore());
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store carbon_metric: " + e.getMessage());
        }

        return result;
    }

    /**
     * Read the most recent carbon_metric row already stored for a project.
     * Returns null if none found or if the stored total is zero.
     */
    private CarbonMetricResult readLatestCarbonMetric(int projectId) {
        String sql = "SELECT scope1_tco2, scope2_tco2, scope3_tco2, total_tco2, method, data_quality_score " +
                     "FROM carbon_metric WHERE project_id = ? " +
                     "ORDER BY metric_date DESC, id DESC LIMIT 1";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    double total = rs.getDouble("total_tco2");
                    if (!rs.wasNull() && total > 0) {
                        CarbonMetricResult r = new CarbonMetricResult();
                        r.setScope1Tco2(nullableDouble(rs, "scope1_tco2"));
                        r.setScope2Tco2(nullableDouble(rs, "scope2_tco2"));
                        r.setScope3Tco2(nullableDouble(rs, "scope3_tco2"));
                        r.setTotalTco2(total);
                        r.setMethod(rs.getString("method"));
                        double dq = rs.getDouble("data_quality_score");
                        r.setDataQualityScore(rs.wasNull() ? 70.0 : dq);
                        return r;
                    }
                }
            }
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] readLatestCarbonMetric failed: " + e.getMessage());
        }
        return null;
    }

    private Double nullableDouble(ResultSet rs, String col) throws SQLException {
        double v = rs.getDouble(col);
        return rs.wasNull() ? null : v;
    }

    private double toEnergyKwh(double value, String unit) {
        if (value <= 0) return 0.0;
        String normalized = unit != null ? unit.toLowerCase().trim() : "kwh";
        return switch (normalized) {
            case "mwh" -> value * 1_000.0;
            case "gwh" -> value * 1_000_000.0;
            case "wh"  -> value / 1_000.0;
            default     -> value;
        };
    }

    private CarbonMetricResult fallbackCarbonMetric(ProjectData data) {
        double energy    = pos(data.getConsommationEnergie());
        double transport = pos(data.getDistanceTransport());
        double material  = pos(data.getQuantiteMateriau());
        double waste     = pos(data.getDechetsGeneres());

        double energyKwh = toEnergyKwh(energy, data.getUniteEnergie());

        double s1 = r3((transport * FACTOR_TRANSPORT) + (waste * FACTOR_WASTE));
        double s2 = r3(energyKwh * FACTOR_ENERGY);
        double s3 = r3(material * FACTOR_MATERIAL);

        CarbonMetricResult result = new CarbonMetricResult();
        result.setScope1Tco2(s1);
        result.setScope2Tco2(s2);
        result.setScope3Tco2(s3);
        result.setTotalTco2(r3(s1 + s2 + s3));
        result.setMethod("GL_HEURISTIC_CLIMATIQ_COMPAT_V1");
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 2: HEURISTIC ML FALLBACK
    // Mirrors Python predict_model.py logic exactly
    // ══════════════════════════════════════════════════════════════════════

    private MlPredictionResult heuristicMlPrediction(CarbonMetricResult carbon) {
        double totalTco2 = orZero(carbon.getTotalTco2());
        double quality   = orZero(carbon.getDataQualityScore(), 50.0);

        // ESG score formula (mirrors Python)
        double score = Math.max(0, Math.min(10, 9.5 - (totalTco2 / 25.0)));
        int esgScore = (int) Math.round(score);

        // Credibility
        int credibility = (int) Math.round(Math.max(0, Math.min(100, quality)));

        // Carbon risk
        String carbonRisk;
        if (totalTco2 >= 50) carbonRisk = "HIGH";
        else if (totalTco2 >= 20) carbonRisk = "MEDIUM";
        else carbonRisk = "LOW";

        // Decision
        String decision;
        if ("HIGH".equals(carbonRisk)) {
            decision = "REJECTED";
        } else if (esgScore >= 7 && "LOW".equals(carbonRisk)) {
            decision = "APPROVED";
        } else if (esgScore >= 5) {
            decision = "REVISION_REQUIRED";
        } else {
            decision = "REJECTED";
        }

        MlPredictionResult result = new MlPredictionResult();
        result.setPredictedEsgScore(esgScore);
        result.setCredibilityScore(credibility);
        result.setCarbonRisk(carbonRisk);
        result.setDecision(decision);
        result.setModelVersion("java-heuristic-v1");
        return result;
    }

    private FraudAssessmentResult heuristicFraudAssessment(ProjectData data, CarbonMetricResult carbon) {
        double energy    = pos(data.getConsommationEnergie());
        double transport = pos(data.getDistanceTransport());
        double material  = pos(data.getQuantiteMateriau());
        double declared  = pos(data.getEmissionsEstimees());
        double computed  = orZero(carbon.getTotalTco2());

        int missingNumeric  = (energy == 0 ? 1 : 0) + (declared == 0 ? 1 : 0);
        int missingOptional = (transport == 0 ? 1 : 0) + (material == 0 ? 1 : 0);

        double distPerMat = material > 0 ? transport / material : 0.0;
        double emPerEn    = energy   > 0 ? declared  / energy   : 0.0;
        double gapBase    = Math.max(Math.max(computed, declared), 1.0);
        double carbonGap  = Math.abs(declared - computed) / gapBase;

        double risk = 0.0;
        risk += Math.min(0.10, missingNumeric  * 0.08);
        risk += Math.min(0.06, missingOptional * 0.015);
        risk += Math.min(0.10, carbonGap       * 0.10);

        if (computed >= 80)      risk += 0.25;
        else if (computed >= 50) risk += 0.12;

        if (distPerMat > 14)      risk += 0.12;
        else if (distPerMat > 10) risk += 0.06;

        if (emPerEn > 0.06)      risk += 0.10;
        else if (emPerEn > 0.04) risk += 0.05;

        risk = Math.max(0.0, Math.min(1.0, risk));
        double anomaly = Math.max(0.0, Math.min(3.0, 1.05 * risk));

        boolean hardSignal = missingNumeric >= 2 || distPerMat > 20 || emPerEn > 0.08 || computed >= 80;
        boolean fraudFlag  = hardSignal || risk >= 0.65;

        FraudAssessmentResult result = new FraudAssessmentResult();
        result.setFraudRiskScore(r4(risk));
        result.setFraudAnomalyScore(r4(anomaly));
        result.setFraudFlag(fraudFlag);
        result.setModelVersion("java-heuristic-v1");
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // STEP 3: GREEN CREDIT DISPATCH
    // ══════════════════════════════════════════════════════════════════════

    private GreenCreditResult computeGreenCredits(Projet project,
                                                   CarbonMetricResult carbon,
                                                   FraudAssessmentResult fraud,
                                                   MlPredictionResult ml) {
        double actualTco2   = orZero(carbon.getTotalTco2());
        double quality      = orZero(carbon.getDataQualityScore(), 50.0);
        double avoidedTco2  = baselineService.calculateAvoided(ProjectData.from(project), actualTco2);
        double fraudRisk    = orZero(fraud.getFraudRiskScore());
        int    esgScore     = ml.getPredictedEsgScore() != null ? ml.getPredictedEsgScore() : 0;

        // Eligibility check
        EligibilityCheckService.EligibilityResult eligibility =
            eligibilityService.check(project.getStatutEvaluation(), avoidedTco2, quality, fraud);

        if (!eligibility.eligible()) {
            GreenCreditResult r = GreenCreditResult.notEligible(eligibility.reason());
            r.setBaselineTco2(baselineService.calculateBaseline(ProjectData.from(project)));
            r.setActualTco2(actualTco2);
            r.setAvoidedTco2(avoidedTco2);
            return r;
        }

        // Calculate credits
        double credibilityFactor = eligibilityService.credibilityFactor(quality, fraudRisk, avoidedTco2);
        double esgMultiplier     = eligibilityService.esgMultiplier(esgScore);
        double credits           = r3(avoidedTco2 * credibilityFactor * esgMultiplier);

        String formula = String.format("%.3f tCO2e × %.2f credibility × %.2f ESG = %.3f credits",
            avoidedTco2, credibilityFactor, esgMultiplier, credits);

        String badge = credits > 10 ? "High Impact" : credits > 1 ? "Eligible" : "Low Impact";

        GreenCreditResult result = new GreenCreditResult();
        result.setBaselineTco2(baselineService.calculateBaseline(ProjectData.from(project)));
        result.setActualTco2(actualTco2);
        result.setAvoidedTco2(avoidedTco2);
        result.setDispatchedCredits(credits);
        result.setCredibilityFactor(credibilityFactor);
        result.setEsgMultiplier(esgMultiplier);
        result.setEligible(true);
        result.setStatusBadge(badge);
        result.setFormula(formula);
        result.setExplanation(eligibility.reason());
        return result;
    }

    // ══════════════════════════════════════════════════════════════════════
    // DB PERSISTENCE
    // ══════════════════════════════════════════════════════════════════════

    private void storeMlPrediction(int projectId, MlPredictionResult ml, int expertId) {
        String sql = "INSERT INTO ml_predictions " +
                     "(project_id, predicted_esg_score, credibility_score, carbon_risk, " +
                     " decision, recommendations, model_version, created_by_user_id, created_at) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW())";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setIntOrNull(ps, 2, ml.getPredictedEsgScore());
            setIntOrNull(ps, 3, ml.getCredibilityScore());
            ps.setString(4, ml.getCarbonRisk());
            ps.setString(5, ml.getDecision());
            ps.setString(6, ml.getRecommendations());
            ps.setString(7, ml.getModelVersion());
            ps.setInt(8, expertId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store ml_predictions: " + e.getMessage());
        }
    }

    private void storeFraudAssessment(int projectId, FraudAssessmentResult fraud) {
        String sql = "INSERT INTO ml_fraud_assessment " +
                     "(project_id, fraud_risk_score, anomaly_score, fraud_flag, " +
                     " suspicious_features, model_version, created_at) " +
                     "VALUES (?, ?, ?, ?, ?, ?, NOW())";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, projectId);
            setDoubleOrNull(ps, 2, fraud.getFraudRiskScore());
            setDoubleOrNull(ps, 3, fraud.getFraudAnomalyScore());
            ps.setBoolean(4, fraud.isFraudFlag());
            ps.setString(5, fraud.getFraudReasons() != null
                ? String.join(" | ", fraud.getFraudReasons()) : null);
            ps.setString(6, fraud.getModelVersion());
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to store ml_fraud_assessment: " + e.getMessage());
        }
    }

    private void updateProjectFraudFields(int projectId, FraudAssessmentResult fraud) {
        String sql = "UPDATE projet SET " +
                     "fraud_risk_score=?, fraud_anomaly_score=?, fraud_flag=?, " +
                     "fraud_reasons=?, fraud_scored_at=NOW() WHERE id=?";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            setDoubleOrNull(ps, 1, fraud.getFraudRiskScore());
            setDoubleOrNull(ps, 2, fraud.getFraudAnomalyScore());
            ps.setBoolean(3, fraud.isFraudFlag());
            ps.setString(4, fraud.getFraudReasons() != null
                ? String.join(" | ", fraud.getFraudReasons()) : null);
            ps.setInt(5, projectId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to update projet fraud fields: " + e.getMessage());
        }
    }

    private void updateProjectGreenCreditFields(int projectId,
                                                 GreenCreditResult credit,
                                                 CarbonMetricResult carbon) {
        String sql = "UPDATE projet SET " +
                     "baseline_tco2=?, actual_tco2=?, avoided_tco2=?, " +
                     "dispatched_green_credits=?, green_credit_credibility_factor=?, " +
                     "green_credit_esg_multiplier=?, green_credit_dispatch_status=?, " +
                     "green_credit_status_badge=?, green_credit_formula=?, " +
                     "green_credit_last_computed_at=NOW() WHERE id=?";
        try (Connection conn = MyConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            setDoubleOrNull(ps, 1, credit.getBaselineTco2());
            setDoubleOrNull(ps, 2, credit.getActualTco2());
            setDoubleOrNull(ps, 3, credit.getAvoidedTco2());
            setDoubleOrNull(ps, 4, credit.getDispatchedCredits());
            setDoubleOrNull(ps, 5, credit.getCredibilityFactor());
            setDoubleOrNull(ps, 6, credit.getEsgMultiplier());
            ps.setString(7, credit.isEligible() ? "DISPATCHED" : "NOT_ELIGIBLE");
            ps.setString(8, credit.getStatusBadge());
            ps.setString(9, credit.getFormula());
            ps.setInt(10, projectId);
            ps.executeUpdate();
        } catch (SQLException e) {
            System.err.println("[ExpertWorkflow] Failed to update projet green credit fields: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // DATA QUALITY SCORE
    // ══════════════════════════════════════════════════════════════════════

    private double computeDataQualityScore(ProjectData data, List<String> errors) {
        int score = 100;

        // Deduct for missing fields
        if (pos(data.getConsommationEnergie()) == 0) score -= 15;
        if (pos(data.getDistanceTransport())   == 0) score -= 10;
        if (pos(data.getQuantiteMateriau())    == 0) score -= 10;
        if (pos(data.getDechetsGeneres())      == 0) score -= 5;
        if (pos(data.getEmissionsEstimees())   == 0) score -= 10;
        if (data.getSecteur()    == null || data.getSecteur().isBlank())    score -= 5;
        if (data.getLocalisation() == null || data.getLocalisation().isBlank()) score -= 5;

        // Deduct for API errors
        if (errors != null) score -= Math.min(20, errors.size() * 5);

        return Math.max(0, Math.min(100, score));
    }

    // ══════════════════════════════════════════════════════════════════════
    // UTILITIES
    // ══════════════════════════════════════════════════════════════════════

    private double pos(Double v)                    { return (v != null && v > 0) ? v : 0.0; }
    private double orZero(Double v)                 { return v != null ? v : 0.0; }
    private double orZero(Double v, double def)     { return v != null ? v : def; }
    private double r3(double v)                     { return Math.round(v * 1000.0) / 1000.0; }
    private double r4(double v)                     { return Math.round(v * 10000.0) / 10000.0; }

    private void setDoubleOrNull(PreparedStatement ps, int idx, Double v) throws SQLException {
        if (v == null) ps.setNull(idx, Types.DOUBLE);
        else           ps.setDouble(idx, v);
    }

    private void setIntOrNull(PreparedStatement ps, int idx, Integer v) throws SQLException {
        if (v == null) ps.setNull(idx, Types.INTEGER);
        else           ps.setInt(idx, v);
    }
}

